import { DataGrid, type DataGridColumn } from '@design-schema/react';

const COLUMNS: DataGridColumn[] = [
  { key: 'sku', header: 'SKU', isRowHeader: true, width: 120, pinned: 'start' },
  { key: 'name', header: 'Name', width: 200, resizable: true },
  {
    key: 'category',
    header: 'Category',
    editable: true,
    editor: 'select',
    options: [
      { value: 'Lighting', label: 'Lighting' },
      { value: 'Furniture', label: 'Furniture' },
      { value: 'Decor', label: 'Decor' },
    ],
  },
  {
    key: 'qty',
    header: 'Qty',
    align: 'end',
    width: 80,
    sortable: true,
    editable: true,
    editor: 'number',
    validate: (value) => (typeof value === 'number' && value >= 0 ? undefined : 'Qty must be zero or more.'),
  },
  { key: 'price', header: 'Price (USD)', abbr: 'Price in US dollars', align: 'end', sortable: true },
];

<DataGrid
  caption="Price list"
  columns={COLUMNS}
  data={Array.from({ length: 2000 }, (_, i) => ({
    id: `r${i}`,
    sku: `S-${i + 1}`,
    name: `Item ${i + 1}`,
    category: 'Decor',
    qty: i % 50,
    price: (i % 40) + 1,
  }))}
/>
